def max_sum_k_no_adjacent(nums: list[int], k: int) -> int | None:
    n = len(nums)
    if k < 0:
        return None
    if k == 0:
        return 0
    if n < 2 * k - 1:
        return None
    if k == 1:
        return max(nums)

    NEG_INF = float("-inf")

    # dp[i][j] = max sum choosing exactly j elements from nums[i:]
    # with no two adjacent, and element i is available to be chosen.
    # Dimensions: (n+2) x (k+1), padded with two extra rows of -inf at the bottom.
    dp = [[NEG_INF] * (k + 1) for _ in range(n + 2)]
    for i in range(n + 2):
        dp[i][0] = 0

    for i in range(n - 1, -1, -1):
        for j in range(1, k + 1):
            take = nums[i] + dp[i + 2][j - 1]
            skip = dp[i + 1][j]
            if take > skip:
                dp[i][j] = take
            else:
                dp[i][j] = skip

    result = dp[0][k]
    return result if result != NEG_INF else None
```

