def max_sum_k_no_adjacent(nums: list[int], k: int) -> int | None:
    n = len(nums)
    if k == 0:
        return 0
    if k > (n + 1) // 2:
        return None

    # dp[i][j] = max sum using first i elements (0..i-1) picking exactly j non-adjacent
    # Use -inf for impossible states
    neg_inf = float('-inf')
    dp = [[neg_inf] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 0

    for i in range(1, n + 1):
        # copy previous row (not picking nums[i-1])
        for j in range(k + 1):
            dp[i][j] = dp[i-1][j]
        # pick nums[i-1] if possible
        for j in range(1, k + 1):
            if i >= 2:
                if dp[i-2][j-1] != neg_inf:
                    dp[i][j] = max(dp[i][j], dp[i-2][j-1] + nums[i-1])
            else:  # i == 1, only j==1 possible
                if j == 1:
                    dp[i][j] = max(dp[i][j], nums[i-1])

    result = dp[n][k]
    return result if result != neg_inf else None
```

