def max_sum_k_no_adjacent(nums: list[int], k: int) -> int | None:
    n = len(nums)
    if k == 0:
        return 0
    if k > (n + 1) // 2:
        return None

    dp = {}

    def solve(index, count):
        if count == 0:
            return 0
        if index >= n:
            return float('-inf')

        if (index, count) in dp:
            return dp[(index, count)]

        # Option 1: Include the current element
        include = nums[index] + solve(index + 2, count - 1)

        # Option 2: Exclude the current element
        exclude = solve(index + 1, count)

        dp[(index, count)] = max(include, exclude)
        return dp[(index, count)]

    result = solve(0, k)
    return result if result != float('-inf') else None
```

