def weighted_edit(a: str, b: str) -> int:
    m, n = len(a), len(b)
    # dp[i][j] = cost to convert a[:i] to b[:j]
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Base cases
    for i in range(m + 1):
        dp[i][0] = i * 2  # Delete all characters of a
    for j in range(n + 1):
        dp[0][j] = j * 1  # Insert all characters of b

    # Fill DP table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                cost = 0
            else:
                cost = 3

            dp[i][j] = min(
                dp[i - 1][j] + 2,      # Delete a[i-1]
                dp[i][j - 1] + 1,      # Insert b[j-1]
                dp[i - 1][j - 1] + cost # Substitute or Match
            )

    return dp[m][n]
